@load_moler_configuration_from_tl()
def upload_bip_mirroring_scripts(gnb_id=0, local_scripts_dir=None, du_id=0, bts_type="GNB"):
    """
    Upload all scripts needed for capture BIP logs.

    :param gnb_id: BTS(gNB) id - related to Test Line configuration.
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :param bts_type: GNB|ENB
    :param local_scripts_dir: path to directory where BIP scripts are located.
    """
    bip_collector = BipCollectorFactory(bts_type=bts_type, bts_id=gnb_id, du_id=du_id)
    bip_collector.upload_mirroring_scripts(local_scripts_dir=local_scripts_dir)


@load_moler_configuration_from_tl()
def enable_bip_remote_streaming(gnb_id=0, du_id=0, bts_type="GNB"):
    """
    Enable remote streaming BIP logs.

    :param gnb_id: BTS(gNB) id - related to Test Line configuration.
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :param bts_type: GNB|ENB
    """
    bip_collector = BipCollectorFactory(bts_type=bts_type, bts_id=gnb_id, du_id=du_id)
    bip_collector.enable_remote_streaming()


@load_moler_configuration_from_tl()
def disable_bip_remote_streaming(gnb_id=0, du_id=0, bts_type="GNB"):
    """
    Disable remote streaming BIP logs.

    :param gnb_id: BTS(gNB) id - related to Test Line configuration.
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :param bts_type: GNB|ENB
    """
    bip_collector = BipCollectorFactory(bts_type=bts_type, bts_id=gnb_id, du_id=du_id)
    bip_collector.disable_remote_streaming()


@load_moler_configuration_from_tl()
def start_bip_trace_log_capturing(gnb_id=0, mode='background', timeout=60 * 60, mirroring_script_params={}, du_id=0,
                                  bts_type="GNB"):
    """
    Start capturing BIP logs.
    :param gnb_id: BTS(gNB) id - related to Test Line configuration
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :param mode: mode of running script, default background. Possible values: foreground/background
    :param timeout: timeout for running command
    :param mirroring_script_params: All available params are in gnbMirroringConfig.sh file. If some
        of params is not passed then will be get directly from gnbMirroringConfig.sh file

        Eg:
        mirroring_script_params = {
            'filtering'='off',
            'syscom_mirroring'='true',
            'carrier_aggregation'='true',
            'mirroring_mode'='local'
        }
    :param bts_type: GNB|ENB
    """
    bip_collector = BipCollectorFactory(bts_type=bts_type, bts_id=gnb_id, du_id=du_id)
    bip_collector.start_log_capturing(mode, int(timeout), mirroring_script_params)


@load_moler_configuration_from_tl()
def stop_bip_trace_log_capturing(gnb_id=0, du_id=0, bts_type="GNB"):
    """
    Stop gnbMirroring.sh script and check if all processes are killed.

    :param gnb_id: BTS(gNB) id - related to Test Line configuration
    :param du_id: DU id(Distributed Unit) - id related to Tupload_mirroring_scriptsest Line configuration - gnb.dus[]
    :param bts_type: GNB|ENB
    """
    bip_collector = BipCollectorFactory(bts_type=bts_type, bts_id=gnb_id, du_id=du_id)
    bip_collector.stop_log_capturing()


@load_moler_configuration_from_tl()
def download_bip_logs(gnb_id=0, download_dir=None, new_file_name=None, timeout=5 * 60, du_id=0, bts_type="GNB"):
    """
    Download pcap bib logs from gNB to local machine.

    :param gnb_id: BTS(gNB) id - related to Test Line configuration.
    :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :param bts_type: GNB|ENB
    :param download_dir: path to directory where file will be downloaded. If not passed Robot
                        output dir will be used.
    :param new_file_name: set if you would like scp file with new name.
    :param timeout: timeout for scp.
    """
    if download_dir is None:
        download_dir = get_builtin_value('OUTPUT DIR')
    timeout = time_to_seconds(time=timeout)

    bip_collector = BipCollectorFactory(bts_type=bts_type, bts_id=gnb_id, du_id=du_id)
    bip_collector.download_bip_logs(download_dir=download_dir, new_file_name=new_file_name, timeout=timeout)


class BipCollectorSsh(object):
    script_name = 'gnbMirroring.sh'
    config_name = 'gnbMirroringConfig.sh'
    gulp = 'gulp'
    remote_log_dir = '/tmp/'

    def __init__(self, bts_device_name, remote_dir='/ffs/run/config/scripts/', bts_id=0, du_id=0):

        self.bts_name = bts_device_name
        self.bts = DeviceFactory.get_device(bts_device_name)
        self.remote_dir = remote_dir

        self.bts_id = bts_id
        self.du_id = du_id

    def upload_mirroring_scripts(self, local_scripts_dir=None):
        r"""
        Start BIP capture on gnb ASIK to support for 19A, 19B and trunk. Also support feature 1514.
        The scripts location: \\eseefsn50.emea.nsn-net.net\rotta4internal\5G\Oulu_L3_CAMP\gnbMirroring\V23
        The binary file should not be uploaded to robotws5g, so if gulp engine is needed for capturing
        instead of tcpdump, gulp file should be uploaded from other path.

        :param local_scripts_dir: default path is resources/Macro/Python/bts/scripts//BIP/
        """
        # TODO Add support for gulp

        if local_scripts_dir is None:
            local_scripts_dir = self._get_default_scripts_path()

        upload_files(local_dir=local_scripts_dir,
                     local_file='{},{}'.format(self.script_name, self.config_name),
                     remote_dir=self.remote_dir,
                     device_name=self.bts_name,
                     )

        self.bts.goto_state(state=self.bts.initial_state)
        chmod = self.bts.get_cmd(cmd_name='chmod',
                                 cmd_params={'permission': '777', 'filename': "{}/*.sh".format(self.remote_dir)})

        chmod()

        try:
            self._clear_tcpdump_logs()
        except CommandFailure:
            logging.debug("No files to remove")

    @staticmethod
    def _get_default_scripts_path():
        return os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..',
                                            'scripts', 'BIP'))

    def enable_remote_streaming(self):
        """
        Enable remote streaming.
        :return: None
        """
        self._run_mirroring_script(mode='foreground', mirroring_script_params={'mirroring_mode': 'remote'},
                                   timeout=60)

    def disable_remote_streaming(self):
        """
        Disable remote streaming.
        :return: None
        """
        self._run_mirroring_script(mode='foreground', mirroring_script_params={'mirroring_mode': 'local',
                                                                               'capturing_time_seconds': '1'},
                                   timeout=60)

    def start_log_capturing(self, mode='background', timeout=60 * 60, mirroring_script_params={}):
        """
        Start capturing BIP logs.
        :param mode: mode of running script, default background. Possible values: foreground/background
        :param timeout: timeout for running command
        :param mirroring_script_params: All available params are in gnbMirroringConfig.sh file. If some
            of params is not passed then will be get directly from gnbMirroringConfig.sh file

            Eg:
            mirroring_script_params = {
                'filtering'='off',
                'syscom_mirroring'='true',
                'carrier_aggregation'='true',
                'mirroring_mode'='local'
            }
        """
        self._run_mirroring_script(mode=mode, timeout=timeout, mirroring_script_params=mirroring_script_params)

    def _run_mirroring_script(self, mode='background', timeout=60 * 60, mirroring_script_params={}):
        """
        Run gnbMirroring.sh script with passed mirroring_script_params params.
        :param mode: mode of running script, default background. Possible values: foreground/background
        :param timeout: timeout for running command
        :param mirroring_script_params: All available params are in gnbMirroringConfig.sh file. If some
            of params is not passed then will be get directly from gnbMirroringConfig.sh file

            Eg:
            mirroring_script_params = {
                'filtering'='off',
                'syscom_mirroring'='true',
                'carrier_aggregation'='true',
                'mirroring_mode'='local'
            }
        """
        options = self._get_bip_options(mirroring_script_params)
        cmd_string = "sh {} {}".format(os.path.join(self.remote_dir, self.script_name), options)

        self.bts.goto_state(state=self.bts.initial_state)
        collect_bip = self.bts.get_cmd(cmd_name='run_script', cmd_params={'script_command': cmd_string})

        if mode == 'background':
            pattern = r'.*Can be stopped with Ctrl-[cC]. Output is saved to .*'
            verify_script_started = self.bts.get_event(event_name="wait4",
                                                       event_params={
                                                           "detect_patterns": [pattern],
                                                           "till_occurs_times": 1}
                                                       )
            verify_script_started.start()
            collect_bip.start(timeout=timeout)
            verify_script_started.await_done(timeout=20)
        else:
            collect_bip(timeout=timeout)

    @staticmethod
    def _get_bip_options(mirroring_script_params):
        options = ''
        if mirroring_script_params:
            for param in mirroring_script_params:
                options = "{} --{}='{}'".format(options, param, mirroring_script_params[param])

        return options

    def stop_log_capturing(self):
        """
        Stop gnbMirroring.sh script and check if all processes are killed.
        """
        self.bts.io_connection.moler_connection.sendline(data=chr(3))
        pids = self._get_script_pid()
        if pids:
            self._kill_process(pids=pids)

    def _get_script_pid(self):
        script_process = []
        ps = self.bts.get_cmd(cmd_name='ps', cmd_params={'options': '-ef'})
        running_proccess = ps()
        for process in running_proccess:
            if self.script_name in process['CMD'] or 'tcpdump' in process['CMD']:
                logging.debug("PID: {}, CMD {}".format(process['PID'], process['CMD']))
                script_process.append(process['PID'])

        return script_process

    def _kill_process(self, pids):
        pid_str = " ".join([str(pid) for pid in pids])
        kill = self.bts.get_cmd(cmd_name='kill', cmd_params={'pid': pid_str})
        kill()

    def download_bip_logs(self, download_dir, new_file_name=None, timeout=120):
        """
        Download pcap bib logs from gNB to local machine.(Works only for local mode)

        :param download_dir: path to directory where file will be downloaded.
        :param new_file_name: set if you would like scp file with new name.
        :param timeout: timeout for scp.

        """
        download_files(local_dir=download_dir,
                       remote_file='tcpdump*L2L1*',
                       remote_dir=self.remote_log_dir,
                       device_name=self.bts_name,
                       new_file_name=new_file_name,
                       timeout=timeout
                       )

        self._clear_tcpdump_logs()

    def _clear_tcpdump_logs(self):
        self.bts.goto_state(state=self.bts.initial_state)
        rm = self.bts.get_cmd(cmd_name='rm', cmd_params={'file': '{}tcpdump*L2L1*'.format(self.remote_log_dir),
                                                         'options': '-f'})
        rm()


class BipCollectorAdmin(GenericLog):

    def __init__(self, bts_type='GNB', bts_id=0, du_id=0):
        super(BipCollectorAdmin, self).__init__(bts_type)
        self.credentials = get_web_credentials_for_du(bts_id, du_id, bts_type)
        self.collector_name = '{}_{}{}_DU{}'.format(self.__class__.__name__, bts_type, bts_id, du_id)
        self.bts_id = bts_id
        self.du_id = du_id

    @staticmethod
    def upload_mirroring_scripts(local_scripts_dir=None):
        logging.warning("upload_bip_mirroring_scripts is deprecated since 22R4 release")

    @staticmethod
    def enable_remote_streaming():
        logging.warning("enable_bip_remote_streaming is deprecated since 22R4 release")

    @staticmethod
    def disable_remote_streaming():
        logging.warning("disable_bip_remote_streaming is deprecated since 22R4 release")

    def setup_log_collector(self, timeout=600):
        """
        Create bip collector core object and setup the collector
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        biplog = self._try_to_get_robot_builtin_instance('biplog', 'taf.collectors.l1l2bip')

        bip_collector = core.get_alias_value(alias=self.collector_name)
        if not bip_collector:
            web_service = {"host": self.credentials["ip"], "user": self.credentials["username"],
                           "password": self.credentials["password"], "port": 443}
            l1l2bip().create_interface_mirroring_l1l2bip_collector(name=self.collector_name, webservice=web_service,
                                                                   timeout=timeout)
            biplog.set_suite_alias(alias=self.collector_name)
            core.setup_collectors(names=self.collector_name)
        else:
            logging.debug("BipLog collector with name {} already exist. Skipping setup procedure".
                          format(self.collector_name))

    def start_log_capturing(self, mode='background', timeout=60 * 60, mirroring_script_params={}):
        """
        Start L1-L2 interface mirroring

        :return detailed_output: (bool)  Return full request response when True, defaults set to False.
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        biplog_collector = core.get_alias_value(alias=self.collector_name)
        if not biplog_collector:
            self.setup_log_collector(timeout=timeout)
        elif biplog_collector._is_started:
            logging.debug("BipLog for {} is already started. Skipping starting procedure".format(self.collector_name))
            return
        core.start_collectors(names=self.collector_name)

    def stop_log_capturing(self):
        """
        Stop L1-L2 interface mirroring

        :return detailed_output: (bool)  Return full request response when True, defaults set to False.
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        biplog_collector = core.get_alias_value(alias=self.collector_name)
        if biplog_collector and not biplog_collector._is_started:
            logging.debug("BipLog for {} is not started. Skipping stopping procedure".format(self.collector_name))
            return
        core.stop_collectors(names=self.collector_name)

    def download_bip_logs(self, download_dir, new_file_name=None, timeout=180):
        """
        Download pcap bib logs from gNB to local machine.(Works only for local mode)

        :param download_dir: path to directory where file will be downloaded.
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        biplog_collector = core.get_alias_value(alias=self.collector_name)
        if biplog_collector and biplog_collector._is_started:
            logging.debug("BipLog for {} is still running. Triggering stop procedure".format(self.collector_name))
            core.stop_collectors(names=self.collector_name)
        org_timeout = biplog_collector._timeout
        biplog_collector._timeout = timeout
        core.collect_collectors(names=self.collector_name, target_dir=download_dir)
        biplog_collector._timeout = org_timeout


class BipCollectorFactory(object):
    """
    BipCollectorFactory class.
    """

    __collector_instance = None

    @staticmethod
    def __is_release_higher_than_22r4(bts_id=0, du_id=0, bts_type="GNB"):
        """
        Check if software release is higher than 22r4.

        :param bts_id: BTS(gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bts_type: GNB|ENB
        """
        sw_release = GenericDuOperations(bts_type).get_bts_sw_release_name(bts_id, du_id)
        match = re.search(r'((?P<NUMBER>\d+)R(?P<VERSION>([A-C])|(\d+)))', sw_release)
        if match:
            release_number = int(match.group('NUMBER'))
            release_version = int(match.group('VERSION'))
            return True if release_number > 22 or (release_number == 22 and release_version >= 4) else False

    def __new__(cls, bts_type="GNB", bts_id=0, du_id=0):
        """
        Create proper bip collector instance depending on the software release name.

        :param gnb_id: BTS(gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param bts_type: GNB|ENB
        :return: bip_collector object of class BipCollectorSsh|BipCollectorAdmin
        """
        if cls.__collector_instance is None:
            if not is_testline_of_cloud_type(bts_id, bts_type) and BipCollectorFactory.__is_release_higher_than_22r4():
                cls.__collector_instance = BipCollectorAdmin(bts_type, bts_id, du_id)
            else:
                cls.__collector_instance = \
                    BipCollectorSsh(bts_device_name=device_aliases.ssh_bts_du.format(bts_type, bts_id, du_id),
                                    bts_id=bts_id, du_id=du_id)
        return cls.__collector_instance
